import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { searchServices } from '../services/api';

export default function SearchPage() {
  const { keyword } = useParams();
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchSearchResults = async () => {
      try {
        const data = await searchServices(keyword);
        setServices(data);
      } catch (err) {
        console.error('Failed to fetch search results', err);
      } finally {
        setLoading(false);
      }
    };
    fetchSearchResults();
  }, [keyword]);

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <button onClick={() => navigate('/')} style={{ marginBottom: '20px', cursor: 'pointer' }}>
        &larr; Back Home
      </button>
      <h2>Search Results for "{keyword}"</h2>

      {loading ? (
        <p>Loading...</p>
      ) : services.length > 0 ? (
        <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
          {services.map((service) => (
            <div 
              key={service._id} 
              onClick={() => navigate(`/service/${service._id}`)}
              style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px', width: '250px', cursor: 'pointer' }}
            >
              <h3>{service.title}</h3>
              <p><strong>Category:</strong> {service.category}</p>
              <p><strong>Price:</strong> ৳{service.price}</p>
              <p style={{ color: '#555', fontSize: '14px' }}>{service.description.substring(0, 60)}...</p>
            </div>
          ))}
        </div>
      ) : (
        <p>No services matched your search.</p>
      )}
    </div>
  );
}
